import React, { forwardRef, isValidElement, useImperativeHandle } from 'react';
import { Container, Stack } from '@fiverr-private/layout_components';
import { Popover, PopoverAnchor, PopoverContent, usePopoverContext } from '@fiverr-private/popover';
import { renderChildren } from '@fiverr-private/ui_utils';
import Tag from '../../Tag';
import { ShowMoreTagProps } from '../types';

const ShowMoreAnchor = forwardRef<HTMLElement, Partial<ShowMoreTagProps>>(
  ({ size, variant, theme, hiddenTagsCount, children }: Partial<ShowMoreTagProps>, ref) => {
    const {
      floatingData: { refs },
    } = usePopoverContext();
    useImperativeHandle(ref, () => refs.reference.current as HTMLElement);

    return (
      <Container cursor="pointer">
        <Tag size={size} variant={variant} theme={theme}>
          {isValidElement(children) || typeof children === 'function'
            ? renderChildren(children, { hiddenTagsCount })
            : `+ ${hiddenTagsCount}`}
        </Tag>
      </Container>
    );
  }
);

ShowMoreAnchor.displayName = 'ShowMoreAnchor';

const ShowMoreTag = forwardRef<HTMLElement, ShowMoreTagProps>(
  (
    { hiddenTagsCount, hiddenTags, size = 'md', variant = 'filled', theme = 'light', children }: ShowMoreTagProps,
    ref
  ) => (
    <Popover>
      <PopoverAnchor>
        <ShowMoreAnchor ref={ref} size={size} variant={variant} theme={theme} hiddenTagsCount={hiddenTagsCount}>
          {children}
        </ShowMoreAnchor>
      </PopoverAnchor>
      <PopoverContent {...(theme === 'dark' && { backgroundColor: 'grey_1200' })} disablePadding>
        <Stack direction="column" overflow="auto" maxHeight="323px" padding="5">
          {hiddenTags}
        </Stack>
      </PopoverContent>
    </Popover>
  )
);

ShowMoreTag.displayName = 'ShowMoreTag';
Object.assign(ShowMoreTag, { id: 'ShowMoreTag' });

export default ShowMoreTag;
